<?php
require_once __DIR__.'/includes/security.php';require __DIR__.'/includes/db.php';require __DIR__.'/includes/customer-auth.php';
[$items,$subtotal]=cart_items($pdo);if(!$items){header('Location: cart.php');exit;}$customer=current_customer();$addresses=[];$defaultAddress=null;
if($customer){$s=$pdo->prepare('SELECT * FROM customer_addresses WHERE customer_id=? ORDER BY is_default DESC,id DESC');$s->execute([$customer['id']]);$addresses=$s->fetchAll();foreach($addresses as $a)if($a['is_default']){$defaultAddress=$a;break;}}
$shipping=$subtotal>=500000?0:20000;$error='';$selectedId=(int)($_POST['address_id']??($defaultAddress['id']??0));
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$saveAddress=isset($_POST['save_address']);
 if($customer&&$selectedId){$s=$pdo->prepare('SELECT * FROM customer_addresses WHERE id=? AND customer_id=?');$s->execute([$selectedId,$customer['id']]);$a=$s->fetch();if(!$a){$error='Alamat tidak valid. Silakan pilih alamat tersimpan atau isi alamat baru.';}else{$name=$a['recipient_name'];$phone=$a['phone'];$address=$a['address'];$city=$a['city'];$postal=$a['postal_code'];}}
 else{$name=trim($customer?($_POST['recipient_name']??''):($_POST['customer_name']??''));$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$city=trim($_POST['city']??'');$postal=trim($_POST['postal_code']??'');
  if(mb_strlen($name)<2||mb_strlen($name)>120||!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>190||!preg_match('/^[0-9+(). -]{6,30}$/',$phone)||mb_strlen($address)>5000||!$address||mb_strlen($city)>100||!$city||mb_strlen($postal)>15||!$postal)$error='Mohon lengkapi data penerima dengan benar.';
 }
 if(!$error){try{$pdo->beginTransaction();$fresh=[];$subtotal=0;
  foreach($items as $it){$lock=$pdo->prepare('SELECT id,price,stock,name FROM products WHERE id=? AND active=1 FOR UPDATE');$lock->execute([$it['id']]);$p=$lock->fetch();if(!$p||(int)$p['stock']<$it['quantity'])throw new RuntimeException('Stok '.$it['name'].' tidak mencukupi.');$p['quantity']=$it['quantity'];$fresh[]=$p;$subtotal+=(float)$p['price']*$it['quantity'];}
  $shipping=$subtotal>=500000?0:20000;$total=$subtotal+$shipping;$email=$customer?$customer['email']:strtolower(trim($_POST['email']??''));$customerId=$customer?(int)$customer['id']:null;$number='TK'.date('ymd').strtoupper(bin2hex(random_bytes(8)));
  $ins=$pdo->prepare('INSERT INTO orders(order_number,customer_id,customer_name,email,phone,address,city,postal_code,subtotal,shipping,total) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$ins->execute([$number,$customerId,$name,$email,$phone,$address,$city,$postal,$subtotal,$shipping,$total]);$orderId=(int)$pdo->lastInsertId();
  foreach($fresh as $p){$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,price,quantity) VALUES(?,?,?,?,?)')->execute([$orderId,$p['id'],$p['name'],$p['price'],$p['quantity']]);$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$p['quantity'],$p['id']]);}
  if($customer&&$saveAddress&&!$selectedId){$pdo->prepare('INSERT INTO customer_addresses(customer_id,label,recipient_name,phone,address,city,postal_code,is_default) VALUES(?,?,?,?,?,?,?,?)')->execute([$customerId,trim($_POST['address_label']??'Rumah')?:'Rumah',$name,$phone,$address,$city,$postal,count($addresses)?0:1]);}
  $pdo->commit();$_SESSION['cart']=[];header('Location: success.php?order='.urlencode($number));exit;
 }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex instanceof RuntimeException?$ex->getMessage():'Pesanan belum dapat disimpan. Silakan coba kembali.';}}
}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout — TokoKita</title><link rel="stylesheet" href="assets/style.css"><style>.address-choice{display:block;border:1px solid var(--line);border-radius:8px;padding:12px;margin:10px 0;cursor:pointer}.address-choice:has(input:checked){border-color:#304c3d;background:#f4f7f3}.newaddr{border-top:1px solid var(--line);margin-top:18px;padding-top:16px}.hide{display:none!important}.account-tip{font-size:13px;background:#f4f6f2;padding:12px;border-radius:8px;margin-bottom:15px}</style></head><body><?php include __DIR__.'/includes/header.php'?><?php customer_nav()?><main class="wrap"><div class="crumb"><a href="index.php">Beranda</a> / <a href="cart.php">Keranjang</a> / Checkout</div><h1 class="page-title">Selesaikan pesanan</h1><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><div class="checkout-layout"><form class="panel" method="post" id="checkout"><h2>Informasi penerima</h2><input type="hidden" name="csrf" value="<?=e(csrf_token())?>">
<?php if($customer):?><p class="account-tip">Masuk sebagai <b><?=e($customer['name'])?></b> (<?=e($customer['email'])?>). Pilih alamat tersimpan atau gunakan alamat lain.</p><?php if($addresses):?><h3>Alamat tersimpan</h3><?php foreach($addresses as $a):?><label class="address-choice"><input type="radio" name="address_id" value="<?=$a['id']?>" <?=$selectedId===$a['id']?'checked':''?>> <b><?=e($a['label'])?><?=$a['is_default']?' · Utama':''?></b><br><span><?=e($a['recipient_name'])?> · <?=e($a['phone'])?> · <?=e($a['address'])?>, <?=e($a['city'])?> <?=e($a['postal_code'])?></span></label><?php endforeach?><label class="address-choice"><input type="radio" name="address_id" value="0" <?=$selectedId===0?'checked':''?>> Gunakan alamat baru</label><?php else:?><p class="muted">Belum ada alamat tersimpan. Isi alamat di bawah; bila disimpan, akan tersedia di checkout berikutnya.</p><?php endif?><div class="newaddr <?=$selectedId?'hide':''?>" id="new-address"><?php else:?><p class="account-tip">Sudah punya akun? <a href="customer/login.php?next=checkout">Masuk</a> untuk memilih alamat tersimpan. Atau lanjutkan sebagai tamu.</p><div class="form-grid"><div class="field"><label>Nama lengkap</label><input name="customer_name" maxlength="120" required value="<?=e($_POST['customer_name']??'')?>"></div><div class="field"><label>Email</label><input type="email" name="email" maxlength="190" required value="<?=e($_POST['email']??'')?>"></div></div><?php endif?>
<?php if($customer):?><input type="hidden" name="customer_name" value="<?=e($customer['name'])?>"><input type="hidden" name="email" value="<?=e($customer['email'])?>"><?php endif?><div class="form-grid"><div class="field"><label>Nama penerima</label><input name="recipient_name" id="recipient" maxlength="120" <?=$customer&&$selectedId?'disabled':''?> required value="<?=e($_POST['recipient_name']??$customer['name']??'')?>"></div><div class="field"><label>Telepon penerima</label><input name="phone" id="phone" maxlength="30" <?=$customer&&$selectedId?'disabled':''?> required value="<?=e($_POST['phone']??$customer['phone']??'')?>"></div><div class="field span"><label>Alamat lengkap</label><textarea name="address" id="address" maxlength="5000" <?=$customer&&$selectedId?'disabled':''?> required><?=e($_POST['address']??'')?></textarea></div><div class="field"><label>Kota / Kabupaten</label><input name="city" id="city" maxlength="100" <?=$customer&&$selectedId?'disabled':''?> required value="<?=e($_POST['city']??'')?>"></div><div class="field"><label>Kode pos</label><input name="postal_code" id="postal" maxlength="15" <?=$customer&&$selectedId?'disabled':''?> required value="<?=e($_POST['postal_code']??'')?>"></div><?php if($customer):?><div class="field"><label>Label alamat</label><input name="address_label" maxlength="60" value="<?=e($_POST['address_label']??'Rumah')?>"></div><div class="field" style="align-self:end"><label><input type="checkbox" name="save_address" <?=isset($_POST['save_address'])?'checked':''?>> Simpan alamat untuk nanti</label></div><?php endif?></div><?php if($customer&&$addresses):?></div><?php endif?><button class="btn full">Buat pesanan · <?=rupiah($subtotal+$shipping)?></button><p class="muted">Pembayaran online dan ongkir aktual belum terintegrasi.</p></form><aside class="panel summary"><h2>Pesananmu</h2><?php foreach($items as $it):?><div class="order-row"><span><?=e($it['name'])?> <small>× <?=$it['quantity']?></small></span><b><?=rupiah($it['line_total'])?></b></div><?php endforeach?><div class="sumline"><span>Subtotal</span><span><?=rupiah($subtotal)?></span></div><div class="sumline"><span>Pengiriman</span><span><?=$shipping?'Rp 20.000':'Gratis'?></span></div><div class="sumline total"><span>Total</span><span><?=rupiah($subtotal+$shipping)?></span></div></aside></div></main><?php if($customer):?><script>const radios=document.querySelectorAll('input[name="address_id"]'),box=document.getElementById('new-address'),fields=['recipient','phone','address','city','postal'].map(id=>document.getElementById(id));function sync(){const fresh=document.querySelector('input[name="address_id"]:checked')?.value==='0';box.classList.toggle('hide',!fresh);fields.forEach(x=>{x.disabled=!fresh;x.required=fresh})}radios.forEach(r=>r.addEventListener('change',sync));sync();</script><?php endif?><?php include __DIR__.'/includes/footer.php'?></body></html>